// `--template` lays a real app over all that (templates.mjs). A short AGENTS.md is written here; the full one needs the
// installed kerf, so bin/create-kerf.mjs runs `kerf agents-md` right after the install. Everything else (.kerf/, the slot
// modules) is generated by `kerf` itself on the first `kerf dev` or `kerf check`, so a scaffold never goes stale against
// the CLI.

import { randomBytes } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, writeFileSync } from 'node:fs'
import { basename, dirname, join } from 'node:path'
import { customAuth } from './data.mjs'
import {
  classes,
  context,
  loginPage,
  sharedAuthTables,
  stackDeps,
  stackFiles,
  TAILWIND_CSS,
  TAILWIND_VITE,
  tailwindPackages,
  todosPage,
  VERSION,
} from './stack.mjs'
import { agentsFile, loadTemplate, withTemplate } from './templates.mjs'

/** What `--ui` takes. */
export const UI = ['veneer', 'headless', 'tailwind', 'none']
/** What `--db` takes. */
export const DB = ['sqlite', 'postgres', 'mysql', 'none']
/** What `--layer` takes. */
export const LAYERS = ['drizzle', 'prisma', 'native']
/** What `--runtime` takes. */
export const RUNTIMES = ['node', 'bun', 'deno']
/** What `--config` takes. */
export const CONFIGS = ['ts', 'json', 'yaml']
export { TEMPLATES, withTemplate } from './templates.mjs'

const json = (v) => JSON.stringify(v, null, 2) + '\n'
const title = (name) => name.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())

/** `kerf.config.ts`, `.json` or `.yaml`: one schema, so the same app in each. */
const LAYER_PLUGIN = {
  prisma: { pkg: '@kerf-js/db/plugin-prisma', name: 'prisma' },
  native: { pkg: '@kerf-js/db/plugin-native', name: 'native' },
}

const appPlugins = ({ ui, layer }) => [
  ...(ui === 'veneer' ? [{ pkg: '@kerf-js/veneer', name: 'veneer' }] : []),
  ...(LAYER_PLUGIN[layer] ? [LAYER_PLUGIN[layer]] : []),
]

/** What each plugin a scaffold picks declares. `kerf check` fails a scaffold where these fall behind the plugin. */
const GRANTS = {
  '@kerf-js/veneer': [
    'fs.read:node_modules/@kerf-js/veneer-core/**',
    'fs.write:$TMPDIR/veneer-seed-*',
    'spawn:node',
  ],
  '@kerf-js/db/plugin-prisma': ['fs.read:prisma/**', 'fs.write:prisma/migrations/**', 'spawn:node'],
  '@kerf-js/db/plugin-native': ['fs.read:migrations/**', 'fs.write:migrations/**'],
}

/** Choosing a plugin here is approving it. There's no install yet, so `kerf plugins approve --all` pins the code later. */
function pluginLock(options) {
  const plugins = Object.fromEntries(
    appPlugins(options).map((p) => [
      p.pkg,
      { version: null, integrity: null, permissions: GRANTS[p.pkg], provides: [], undeclared: [] },
    ]),
  )
  return Object.keys(plugins).length
    ? { '.kerf/plugins.lock.json': json({ version: 1, plugins }) }
    : {}
}

function configFile(format, { ui, label, runtime, layer, veneer }) {
  const plugins = appPlugins({ ui, layer })
  const entry = (p) => (p.pkg === '@kerf-js/veneer' && veneer ? [p.pkg, veneer] : p.pkg)
  const site = { name: label, title: `%s · ${label}`, description: 'Made with kerf.' }
  if (format === 'json') {
    const config = {
      $schema: './.kerf/config.schema.json',
      site,
      ...(plugins.length && { plugins: plugins.map(entry) }),
      ...(runtime !== 'node' && { runtime }),
    }
    return { 'kerf.config.json': json(config) }
  }
  if (format === 'yaml') {
    return {
      'kerf.config.yaml':
        `# yaml-language-server: $schema=./.kerf/config.schema.json\nsite:\n` +
        Object.entries(site)
          .map(([k, v]) => `  ${k}: ${JSON.stringify(v)}\n`)
          .join('') +
        (plugins.length
          ? `plugins:\n${plugins.map((p) => `  - ${JSON.stringify(entry(p))}\n`).join('')}`
          : '') +
        (runtime !== 'node' ? `runtime: ${runtime}\n` : ''),
    }
  }
  return {
    'kerf.config.ts':
      `import { defineConfig } from '@kerf-js/core/config'\n` +
      plugins.map((p) => `import { ${p.name} } from '${p.pkg}/plugin'\n`).join('') +
      `\nexport default defineConfig({\n` +
      `  site: { name: ${JSON.stringify(label)}, title: ${JSON.stringify(site.title)}, description: 'Made with kerf.' },\n` +
      (plugins.length
        ? `  plugins: [${plugins.map((p) => `${p.name}(${p.pkg === '@kerf-js/veneer' && veneer ? JSON.stringify(veneer) : ''})`).join(', ')}],\n`
        : '') +
      (runtime !== 'node' ? `  runtime: '${runtime}',\n` : '') +
      `})\n`,
  }
}

/**
 * The files for an app, as `{ path: text }`.
 * @param {{ ui?: string, name?: string, version?: string, db?: string, layer?: string, auth?: boolean | 'custom', runtime?: string, config?: string, secret?: string, template?: string, pm?: string }} [options]
 */
export function template(options = {}) {
  const {
    ui = 'veneer',
    name = 'kerf-app',
    version = VERSION,
    db = 'none',
    layer = 'drizzle',
    auth = false,
    runtime = 'node',
    config = 'ts',
    secret = randomBytes(32).toString('base64'),
    template: chosen,
  } = withTemplate(options)
  if (!UI.includes(ui)) throw new Error(`--ui must be one of ${UI.join(', ')} (got "${ui}")`)
  if (!DB.includes(db)) throw new Error(`--db must be one of ${DB.join(', ')} (got "${db}")`)
  if (!RUNTIMES.includes(runtime))
    throw new Error(`--runtime must be one of ${RUNTIMES.join(', ')} (got "${runtime}")`)
  if (!CONFIGS.includes(config))
    throw new Error(`--config must be one of ${CONFIGS.join(', ')} (got "${config}")`)
  if (!LAYERS.includes(layer))
    throw new Error(`--layer must be one of ${LAYERS.join(', ')} (got "${layer}")`)
  if (auth && db === 'none')
    throw new Error('--auth keeps users in a database: add --db sqlite, postgres or mysql')
  const overlay = chosen && loadTemplate(chosen)
  const label = title(name)
  const stack = stackDeps({ db, auth: auth === true, layer, version })
  const deps = { '@kerf-js/core': version, '@kerf-js/start': version }
  if (ui === 'veneer') deps['@kerf-js/veneer'] = version
  if (ui === 'headless') deps['@kerf-js/veneer-core'] = version
  if (ui === 'tailwind') Object.assign(stack.dev, tailwindPackages)
  for (const [dep, wanted] of Object.entries(overlay?.dependencies ?? {}))
    deps[dep] = dep.startsWith('@kerf-js/') ? version : wanted

  const files = baseFiles({
    name,
    version,
    db,
    layer,
    ui,
    config,
    label,
    runtime,
    overlay,
    stack,
    deps,
    auth,
  })
  Object.assign(files, pluginLock({ ui, layer }))
  if (options.pm === 'pnpm')
    files['pnpm-workspace.yaml'] = pnpmSettings(db !== 'none' && layer === 'prisma')
  if (ui !== 'veneer') files['src/app.css'] = css(ui)
  if (ui === 'tailwind') files['vite.config.ts'] = TAILWIND_VITE
  if (db !== 'none') {
    Object.assign(files, stackFiles({ db, auth: auth === true, name, secret, layer }))
    if (!overlay) files['src/routes/todos/index.tsx'] = todosPage(ui)
    if (auth === true) files['src/routes/login.tsx'] = loginPage(ui)
    if (auth === 'custom')
      Object.assign(files, {
        'src/auth.server.ts': customAuth,
        'src/context.server.ts': context(true),
      })
  }
  if (overlay) {
    for (const path of Object.keys(files))
      if (/^src\/(routes\/(about\.tsx|todos\/)|server\/todos\.ts)/.test(path)) delete files[path]
    if (auth) files['src/db/auth.ts'] = sharedAuthTables()
    Object.assign(files, overlay.files)
  }
  return files
}

// pnpm 11 and later stop an install at a dependency's build script that nobody has allowed or refused. None is needed:
// esbuild ships its binary as an optional package, and the app's own postinstall runs `prisma generate`.
const pnpmSettings = (prisma) =>
  `allowBuilds:\n  esbuild: false\n${prisma ? "  '@prisma/engines': false\n  prisma: false\n" : ''}`

function baseFiles({
  name,
  version,
  db,
  layer,
  ui,
  config,
  label,
  runtime,
  overlay,
  stack,
  deps,
  auth,
}) {
  return {
    'package.json': json({
      name,
      private: true,
      type: 'module',
      scripts: {
        dev: 'kerf dev',
        build: 'kerf build',
        check: 'kerf check',
        typecheck: 'kerf tsc',
        start: 'kerf start',
        ...(db !== 'none' && { 'db:generate': 'kerf db generate' }),
        ...(db !== 'none' && layer === 'prisma' && { postinstall: 'prisma generate' }),
      },
      dependencies: { ...deps, ...stack.deps },
      devDependencies: { '@kerf-js/cli': version, typescript: '7.0.2', ...stack.dev },
    }),
    ...configFile(config, {
      ui,
      label,
      runtime,
      layer: db === 'none' ? 'drizzle' : layer,
      veneer: overlay?.veneer,
    }),
    'tsconfig.json': json({
      compilerOptions: {
        target: 'es2022',
        module: 'esnext',
        moduleResolution: 'bundler',
        strict: true,
        noEmit: true,
        skipLibCheck: true,
        jsx: 'preserve',
        jsxImportSource: '@kerf-js/core',
        lib: ['es2023', 'dom', 'dom.iterable'],
        paths: { '#/*': ['./src/*'] },
        types: db === 'none' ? ['@kerf-js/core/client'] : ['@kerf-js/core/client', 'node'],
        plugins: [{ name: '@kerf-js/cli/ts-plugin' }],
      },
      include: ['src', ...(config === 'ts' ? ['kerf.config.ts'] : []), '.kerf/*.d.ts'],
    }),
    // VS Code's own tsserver only looks for plugins where it's told, and TypeScript 7 ships no tsserver to select instead.
    '.vscode/settings.json': json({ 'typescript.tsserver.pluginPaths': ['.'] }),
    '.gitignore': `node_modules/\n.kerf/*\n!.kerf/plugins.lock.json\n.output/\ndist/\n${db === 'none' ? '' : '.env\n.data/\n'}${layer === 'prisma' ? 'src/generated/\n' : ''}`,
    'src/routes/_layout.tsx': layout(ui, { db, auth }),
    'src/routes/index.tsx': home(ui, label),
    'AGENTS.md': agentsFile({ ui, db, layer, shipped: overlay?.pages, auth }),
    'src/routes/about.tsx': `export const meta = { title: 'About', description: 'What this app is.' }\n\nexport default function About() {\n  return <h1>About</h1>\n}\n`,
  }
}

/** Write the app into `dir` (which must be missing or empty). */
export function scaffold(dir, options = {}) {
  if (existsSync(dir) && readdirSync(dir).length) throw new Error(`${dir} is not empty`)
  const files = template({
    name: basename(dir)
      .toLowerCase()
      .replace(/[^a-z0-9-_.]/g, '-'),
    ...options,
  })
  for (const [rel, text] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, rel)), { recursive: true })
    writeFileSync(join(dir, rel), text)
  }
  return { dir, files: Object.keys(files) }
}

function layout(ui, options) {
  const text = shell(ui, options)
  return ui === 'tailwind'
    ? text.replace('<nav>', '<nav class="flex gap-4 p-4">').replace('<main>', '<main class="p-4">')
    : text
}

function shell(ui, { db, auth: which }) {
  const auth = which === true
  const imports =
    ui === 'veneer'
      ? ''
      : (ui === 'headless' ? `import '@kerf-js/veneer-core/styles/veneer.css'\n` : '') +
        `import '../app.css'\n`
  const links = db === 'none' ? '' : `\n        <Link href="/todos">Todos</Link>`
  const signOut =
    ui === 'veneer'
      ? '<Button emphasis="ghost" size="sm" onClick={() => signOut()}>Sign out</Button>'
      : '<button type="button" onClick={() => signOut()}>Sign out</button>'
  if (!auth) {
    return `${imports}import { Link, type RouteProps } from '@kerf-js/start'

export default function Root(props: RouteProps) {
  return (
    <>
      <nav>
        <Link href="/">Home</Link>
        <Link href="/about">About</Link>${links}
      </nav>
      <main>{props.children}</main>
    </>
  )
}
`
  }
  return `${imports}${ui === 'veneer' ? "import { Button } from '@kerf-js/veneer'\n" : ''}import { Link, type LoadArgs, type RouteProps } from '@kerf-js/start'
import { me, signOut } from '#/server/session'

export const load = ({ ctx }: LoadArgs) => me.fetch()

export default function Root(props: RouteProps<typeof load>) {
  return (
    <>
      <nav>
        <Link href="/">Home</Link>
        <Link href="/about">About</Link>${links}
        {props.data ? ${signOut} : <Link href="/login">Sign in</Link>}
      </nav>
      <main>{props.children}</main>
    </>
  )
}
`
}

function home(ui, label) {
  if (ui === 'veneer') {
    return `import type { Meta } from '@kerf-js/start'
import { state } from '@kerf-js/core'
import { Badge, Button, Card } from '@kerf-js/veneer'

export const meta: Meta = { title: { absolute: ${JSON.stringify(label)} }, description: ${JSON.stringify(`${label}, made with kerf.`)} }

export default function Home() {
  const count = state(0)
  return (
    <Card eyebrow="kerf + veneer" title=${JSON.stringify(`Welcome to ${label}`)}>
      <p>
        Clicked <Badge>{count.value}</Badge> times.
      </p>
      <Button onClick={() => count.value++}>Click</Button>
    </Card>
  )
}
`
  }
  return `import type { Meta } from '@kerf-js/start'
import { state } from '@kerf-js/core'

export const meta: Meta = { title: { absolute: ${JSON.stringify(label)} }, description: ${JSON.stringify(`${label}, made with kerf.`)} }

export default function Home() {
  const count = state(0)
  return (
    <section class=${JSON.stringify(classes(ui, 'card'))}>
      <h1${named(ui, 'title')}>Welcome to ${label}</h1>
      <button${named(ui, 'button')} type="button" onClick={() => count.value++}>
        Clicked {count.value} times
      </button>
    </section>
  )
}
`
}

const named = (ui, part) => (classes(ui, part) ? ` class="${classes(ui, part)}"` : '')

function css(ui) {
  if (ui === 'tailwind') return TAILWIND_CSS
  // headless rides veneer's tokens (veneer-core's veneer.css, the fluid title size included); none brings its own.
  const v =
    ui === 'headless'
      ? {
          bg: 'var(--veneer-color-page)',
          fg: 'var(--veneer-color-text)',
          accent: 'var(--veneer-color-accent-solid)',
          radius: 'var(--veneer-radius-surface)',
          title: 'var(--veneer-text-title-size)',
        }
      : {
          bg: 'Canvas',
          fg: 'CanvasText',
          accent: 'LinkText',
          radius: '8px',
          title: 'clamp(1.5rem, 1.2rem + 2cqi, 2.5rem)',
        }
  return `:root { color-scheme: light dark; }
body { margin: 0; font-family: system-ui, sans-serif; background: ${v.bg}; color: ${v.fg}; }
nav { display: flex; gap: 1rem; padding: 1rem; }
main { padding: 1rem; max-inline-size: 60rem; margin-inline: auto; }
.card { container-type: inline-size; padding: 1.5rem; border-radius: ${v.radius}; border: 1px solid color-mix(in oklab, currentColor 15%, transparent); }
.card h1 { font-size: ${v.title}; }
button { font: inherit; padding: 0.5rem 1rem; border-radius: ${v.radius}; border: 1px solid ${v.accent}; background: none; color: inherit; }
`
}
